  `group_id` varchar(50) NOT NULL,
  `nurse_id` varchar(50) NOT NULL,
  `year` smallint NOT NULL,
  `month` tinyint NOT NULL,
  `end_shift` varchar(10) DEFAULT NULL,
  `tail_work_streak` int NOT NULL DEFAULT '0',
  `tail_night_streak` int NOT NULL DEFAULT '0',
  `ended_with_e` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_boundary_per_month` (`office_id`,`group_id`,`nurse_id`,`year`,`month`),
  KEY `fk_rbs_group` (`group_id`),
