  CONSTRAINT `fk_rbs_group` FOREIGN KEY (`group_id`) REFERENCES `groups` (`group_id`),
  CONSTRAINT `fk_rbs_nurse` FOREIGN KEY (`nurse_id`) REFERENCES `nurses` (`nurse_id`),
  CONSTRAINT `fk_rbs_office` FOREIGN KEY (`office_id`) REFERENCES `offices` (`office_id`)
